/* Data Engineer Fieldnotes. No backend, tracking, remote scripts or API keys. */
(function () {
'use strict';
const D=globalThis.FIELDNOTES_DATA,C=globalThis.FieldCore,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
if(!D||!C){$('#main').innerHTML='<h1>The study pack could not load.</h1><p>Keep the assets folder beside index.html, then reload.</p>';return;}
const KEY='data-engineer-fieldnotes.v1',Q=Object.fromEntries(D.questions.map(q=>[q.id,q])),L=Object.fromEntries(D.lessons.map(l=>[l.id,l])),G=Object.fromEntries(D.glossary.map(g=>[g.id,g]));
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const doclink=(id)=>{const s=D.sources[id];return s?`<a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)} ↗</a>`:'';};
const refs=ids=>`<ul class="source-list">${[...new Set(ids)].map(id=>D.sources[id]?`<li>${doclink(id)}<small>${e(D.sources[id].publisher)} · primary documentation</small></li>`:'').join('')}</ul>`;
const tag=(text,color='')=>`<span class="chip ${color}">${e(text)}</span>`;
const qlabel=q=>q.origin==='authored'?`Practice ${String(q.number).padStart(2,'0')}`:`Imported #${q.number}`;
const domain=id=>D.domains.find(d=>d.id===Number(id));
const domainLessons=id=>D.lessons.filter(l=>l.domain===id);
function load(){try{const raw=localStorage.getItem(KEY);if(raw)return C.validateProgress(JSON.parse(raw),Object.keys(L),Object.keys(Q),Object.keys(G));}catch(error){try{const raw=localStorage.getItem(KEY);if(raw)localStorage.setItem(KEY+'.recovery',raw);}catch{}}return C.defaultState();}
let state=load(),storageWarned=false,toastTimer,route='',practice={id:null,selected:[],checked:false},bank={query:'',domain:0,origin:'all',status:'all',saved:false,incorrect:false,page:1},english={query:'',saved:false,mode:'list',index:0,flipped:false,deck:[]},lab={tab:'stream',step:0,late:3,days:7,country:'CL',recipe:'stream'},sourceQuery='';
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{if(!storageWarned){storageWarned=true;toast('Browser storage is unavailable. Export progress before closing this page.');}}}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',learn:'<path d="M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3Z"/><path d="M12 6v16"/>',practice:'<rect x="4" y="3" width="16" height="19" rx="2"/><path d="m8 9 2 2 4-4M8 16h8"/>',english:'<path d="m3 18 5-13 5 13M5 14h6M14 7h7M18 4v3M14 12l6 8M21 8c0 5-3 9-7 11"/>',lab:'<path d="M8 3h8M10 3v7L4 20h16l-6-10V3M7 15h10"/>',exam:'<circle cx="12" cy="13" r="8"/><path d="M12 8v5l3 2M9 2h6"/>',sources:'<path d="M5 3h10l4 4v14H5Z"/><path d="M14 3v5h5M8 12h8M8 16h8"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.learn}</svg>`;
function renderNav(active){const nav=[['home','Overview'],['learn','Learning path'],['practice','Practice bank'],['english','English studio'],['lab','Interactive labs'],['exam','Timed practice'],['sources','Sources & review']];$('#navigation').innerHTML=nav.map(([key,label])=>`<a class="nav-item ${active===key?'active':''}" href="#${key}" ${active===key?'aria-current="page"':''}>${icon(key)}<span>${label}</span>${key==='practice'?'<span class="nav-count">399</span>':''}</a>`).join('');$('#breadcrumb').textContent=nav.find(n=>n[0]===active)?.[1]||'Search';$('#english-toggle').setAttribute('aria-pressed',String(state.english));$('#english-status').textContent=state.english?'on':'off';document.body.classList.toggle('english-off',!state.english);}
function pipelineVisual(){return `<div class="pipeline-visual" role="img" aria-label="A streaming analytics route: devices publish to Pub/Sub, Dataflow transforms events, and BigQuery stores the analytical output."><div class="visual-top"><span>A RECORD’S JOURNEY</span><span>STREAMING PATTERN</span></div><svg viewBox="0 0 430 253"><defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 6 3 0 6" fill="none" stroke="#94a8ce" stroke-width="1"/></marker></defs><path d="M163 72H266M320 106V159M266 194H163" stroke="#9db2d8" fill="none" stroke-width="1.2" marker-end="url(#arrow)" class="flow-line"/><g fill="#fff" stroke="#d8e2f2"><rect x="23" y="38" width="140" height="68" rx="9"/><rect x="266" y="38" width="140" height="68" rx="9"/><rect x="266" y="159" width="140" height="68" rx="9"/><rect x="23" y="159" width="140" height="68" rx="9"/></g><g font-size="8" fill="#8592a8"><text x="195" y="62">publish</text><text x="327" y="139">transform</text><text x="188" y="185">write output</text></g><g fill="#3159c9"><rect x="35" y="53" width="25" height="25" rx="6" fill="#edf2ff"/><path d="M41 60h13v12H41zM45 64h5" fill="none" stroke="#3159c9"/><rect x="278" y="53" width="25" height="25" rx="6" fill="#edf2ff"/><circle cx="286" cy="61" r="2"/><circle cx="296" cy="61" r="2"/><circle cx="291" cy="71" r="2"/><path d="m286 63 5 6 5-6" stroke="#3159c9" fill="none"/><rect x="278" y="174" width="25" height="25" rx="6" fill="#fff4db"/><path d="M284 181h13M284 187h13M284 193h13" stroke="#b98c36"/><rect x="35" y="174" width="25" height="25" rx="6" fill="#e9f5f1"/><path d="M41 193v-8M47 193v-13M53 193v-5" stroke="#2b8773" stroke-width="2"/></g><g font-size="11" font-weight="650" fill="#334660"><text x="69" y="62">Device events</text><text x="312" y="62">Pub/Sub</text><text x="312" y="183">Dataflow</text><text x="69" y="183">BigQuery</text></g><g font-size="8" fill="#8490a4"><text x="69" y="78">Preserve event time</text><text x="312" y="78">Decouple producers</text><text x="312" y="199">Validate · window</text><text x="69" y="199">Store · analyze</text></g><text x="215" y="245" text-anchor="middle" font-size="7" fill="#8c99ad">ONE USEFUL PATTERN. THE REQUIREMENTS MAKE THE DECISION.</text></svg></div>`;}
function renderHome(){const done=state.completed.length,next=D.lessons.find(l=>!state.completed.includes(l.id))||D.lessons[0],verified=latestAttempts(true),accuracy=verified.length?Math.round(100*verified.filter(a=>a.correct).length/verified.length):null;
return `<section class="hero"><div><div class="eyebrow">YOUR DATA ENGINEERING JOURNEY</div><h1>Build knowledge.<br><em>Connect the dots.</em></h1><p class="lead">Understand Google Cloud data systems, practice the decisions, and build your English along the way.</p><div class="hero-actions"><a href="#learn/${next.id}" class="button primary">${done?'Continue learning':'Start your learning path'} <span aria-hidden="true">↗</span></a><a href="#practice" class="button quiet">Explore questions →</a></div><div class="hero-note"><span></span>Aligned to the standard Professional Data Engineer guide</div></div>${pipelineVisual()}</section>
<section class="stats" aria-label="Your learning at a glance"><div class="stat"><div class="stat-top">LEARNING PROGRESS<span class="stat-icon">◷</span></div><strong>${Math.round(done/25*100)}<span class="small">%</span></strong><div class="stat-bottom">${done} of 25 lessons completed</div></div><div class="stat"><div class="stat-top">PRACTICE LIBRARY<span class="stat-icon">▤</span></div><strong>399</strong><div class="stat-bottom">349 imported + 50 original</div></div><div class="stat"><div class="stat-top">VERIFIED PRACTICE<span class="stat-icon">◎</span></div><strong>${accuracy===null?'—':accuracy+'<span class="small">%</span>'}</strong><div class="stat-bottom">${verified.length?verified.length+' distinct questions scored':'Your first attempt starts here'}</div></div><div class="stat"><div class="stat-top">ENGLISH TOOLKIT<span class="stat-icon">Aa</span></div><strong>101</strong><div class="stat-bottom">${Object.keys(state.vocab).length} terms saved to your wordbook</div></div></section>
<div class="section-head"><h2>The exam, mapped out.</h2><a class="text-link" href="#learn">View learning path →</a></div><p class="section-intro">Five domains. One connected system. Study the reasoning behind each choice.</p><div class="domain-grid">${D.domains.map(d=>{const ls=domainLessons(d.id),n=ls.filter(l=>state.completed.includes(l.id)).length;return `<a href="#learn/${ls[0].id}" class="domain-card" style="--accent:${d.color}"><div class="domain-top"><span class="domain-index">0${d.id}</span><span class="weight">~${d.weight}%</span></div><h3>${e(d.name)}</h3><p>${e(d.subtitle)}</p><div class="progress-track"><span class="progress-fill" style="--value:${100*n/ls.length}%"></span></div><div class="domain-foot">${n} / ${ls.length} lessons complete</div></a>`;}).join('')}</div>
<div class="home-lower"><section class="panel"><div class="mini-label">${done?'PICK UP WHERE YOU LEFT OFF':'A GOOD PLACE TO BEGIN'}</div><div class="resume-row"><span class="lesson-icon">▱</span><div><h4>${e(next.title)}</h4><p>${e(next.lead)}</p><div class="meta" style="margin-top:10px">${tag('Objective '+next.objective,'blue')}<span>${next.minutes} min · concept + scenario</span></div></div></div><a href="#learn/${next.id}" class="text-link">Open lesson <span aria-hidden="true">→</span></a></section><section class="panel english-card"><div class="mini-label">LEARN THE LANGUAGE OF THE EXAM</div><blockquote data-english>“Choose a solution while minimizing operational overhead.”</blockquote><p class="small" lang="es">Elige una solución reduciendo al mínimo el esfuerzo de administración.</p><a href="#english" class="text-link">Build your English wordbook →</a></section></div>
<div class="section-head"><h2>Practice with the evidence.</h2><a href="#sources" class="text-link">See the content review →</a></div><div class="notice info">The imported questions keep their source keys and explanations. Editorial corrections, legacy wording and missing diagrams are clearly marked. Timed practice uses the 50 original, evidence-linked scenarios.</div>`;}
function storageComparison(){return `<section class="lesson-section"><h2>Compare the storage choices</h2><p class="small muted">Use the access pattern as the first filter, then verify consistency, availability and cost.</p><div class="table-wrap"><table><caption class="sr-only">Data storage decision guide</caption><thead><tr><th>Service</th><th>Good fit and exam signal</th><th>Check the assumption</th></tr></thead><tbody>${D.services.map(s=>`<tr><td><strong>${e(s.name)}</strong><br>${doclink(s.reference)}</td><td data-english>${e(s.fit)}<br><span class="muted">${e(s.signal)}</span></td><td data-english>${e(s.caution)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function renderLearn(id){if(!id||!L[id])return `<div class="page-heading"><div><div class="eyebrow">A SYSTEMATIC STUDY ROUTE</div><h1>Learn the decisions.<br>Then learn the services.</h1><p class="lead">25 concise lessons across all 19 standard-guide objectives. Each combines a concept, a decision, a scenario and primary references.</p></div><a class="button" href="#exam">Check your understanding →</a></div><div class="path-grid">${D.domains.map(d=>`<section class="path-section" style="--accent:${d.color}"><div class="path-section-top"><span class="domain-index">0${d.id}</span><div><h2>${e(d.name)}</h2><div class="small muted">~${d.weight}% of the exam · ${e(d.subtitle)}</div></div></div>${domainLessons(d.id).map(l=>`<a href="#learn/${l.id}" class="lesson-row"><span class="lesson-check ${state.completed.includes(l.id)?'done':''}">${state.completed.includes(l.id)?'✓':''}</span><span class="lesson-info">${e(l.title)}<span class="meta">Objective ${l.objective} · ${l.minutes} min</span></span><span aria-hidden="true">↗</span></a>`).join('')}</section>`).join('')}</div>`;
const l=L[id],idx=D.lessons.indexOf(l),next=D.lessons[idx+1],done=state.completed.includes(id),related=D.questions.filter(q=>q.origin==='authored'&&q.lesson===id).slice(0,3);
return `<a href="#learn" class="back-link">← All lessons</a><div class="study-grid"><article class="lesson-body"><div class="eyebrow">DOMAIN 0${l.domain} · OBJECTIVE ${l.objective}</div><h1>${e(l.title)}</h1><p class="lead" data-english>${e(l.lead)}</p><div class="meta">${tag(l.minutes+' minute lesson','blue')}${tag(done?'Completed':'Ready when you are',done?'green':'')}</div>${l.sections.map(s=>`<section class="lesson-section"><h2>${e(s.title)}</h2><p data-english>${e(s.body)}</p></section>`).join('')}${l.id==='storage-choice'?storageComparison():''}${l.code?`<div class="code-head"><span>ILLUSTRATIVE EXAMPLE</span><button class="button small" data-action="copy-code" data-id="${id}">Copy example</button></div><pre><code>${e(l.code)}</code></pre>`:''}<aside class="trap"><h3>Watch the assumption</h3><p data-english>${e(l.trap)}</p></aside><div class="lesson-end"><button class="button ${done?'':'primary'}" data-action="complete" data-id="${id}">${done?'✓ Completed · mark incomplete':'Mark lesson complete'}</button><a href="${next?'#learn/'+next.id:'#home'}" class="button">${next?'Next lesson →':'Return to overview →'}</a></div></article><aside class="study-side"><section class="panel"><h3>Go to the source</h3><p class="muted">Read the official detail after understanding the principle.</p>${refs(l.references)}</section><section class="panel english-card"><h3>Learn in English, understand deeply</h3><p lang="es">Toca las palabras subrayadas para ver su significado, traducción y pronunciación. Guarda las difíciles en tu vocabulario.</p><a href="#english" class="text-link">Open English studio →</a></section>${related.length?`<section class="panel"><h3>Put the idea to work</h3><div class="stack">${related.map(q=>`<a class="button small" href="#practice/${q.id}">${qlabel(q)} · try a scenario →</a>`).join('')}</div></section>`:''}</aside></div>`;}
function latestAttempts(verifiedOnly=false){const latest=new Map();for(const a of state.attempts)if(!verifiedOnly||a.verified)latest.set(a.id,a);return [...latest.values()];}
function filteredBank(){const wrong=new Set(latestAttempts().filter(a=>!a.correct).map(a=>a.id)),query=bank.query.trim().toLowerCase().replace(/^#/,'');return D.questions.filter(q=>(!bank.domain||q.domain===bank.domain)&&(bank.origin==='all'||q.origin===bank.origin)&&(bank.status==='all'||(bank.status==='needs-review'?q.status!=='reviewed'&&q.status!=='corrected':q.status===bank.status))&&(!bank.saved||state.bookmarks.includes(q.id))&&(!bank.incorrect||wrong.has(q.id))&&(!query||String(q.number)===query||(q.text+' '+q.choices.map(c=>c.text).join(' ')+' '+qlabel(q)).toLowerCase().includes(query)));}
function statusTag(q){if(q.origin==='authored')return tag('Original · evidence-linked','green');return tag({reviewed:'Editorial review',corrected:'Key corrected',disputed:'Key disputed',incomplete:'Missing diagram',legacy:'Legacy wording',conditional:'Conditional answer',unreviewed:'Source key only'}[q.status]||q.status,q.status==='reviewed'?'green':q.status==='corrected'?'blue':q.status==='disputed'?'red':'amber');}
function questionRows(items){return items.map(q=>`<button class="question-row" data-action="open-question" data-id="${q.id}"><span class="question-number">${qlabel(q)}</span><span class="question-row-body"><span class="meta">${statusTag(q)}${tag(domain(q.domain).name)}${q.required>1?tag('Choose '+q.required):''}${state.bookmarks.includes(q.id)?tag('Saved','amber'):''}</span><h3>${e((q.text.length>1100?q.text.slice(-420):q.text).slice(0,230))}${q.text.length>230?'…':''}</h3></span><span class="row-arrow" aria-hidden="true">↗</span></button>`).join('');}
function bankResults(){const items=filteredBank(),pages=Math.max(1,Math.ceil(items.length/12));bank.page=Math.min(pages,bank.page);return `<div class="bank-meta"><span class="small muted">${items.length} questions · page ${bank.page} of ${pages}</span><button class="button quiet small" data-action="clear-bank">Clear filters</button></div>${items.length?`<div class="question-list">${questionRows(items.slice((bank.page-1)*12,bank.page*12))}</div><div class="pagination"><button class="button small" data-action="bank-page" data-dir="-1" ${bank.page===1?'disabled':''}>← Previous</button><span>${bank.page} / ${pages}</span><button class="button small" data-action="bank-page" data-dir="1" ${bank.page===pages?'disabled':''}>Next →</button></div>`:'<div class="empty"><h2>No questions match yet.</h2><p>Try a service name, a question number, or clear the filters.</p></div>'}`;}
function renderBank(){return `<div class="page-heading"><div><div class="eyebrow">PRACTICE WITH UNDERSTANDING</div><h1>Every answer needs a reason.</h1><p class="lead">Explore all 349 imported questions and 50 original scenarios. Reveal the reasoning after you choose, then follow the documentation.</p></div><a href="#exam" class="button primary">Start timed practice ↗</a></div><div class="filterbar"><label class="field grow">FIND A QUESTION<input type="search" id="bank-query" value="${e(bank.query)}" placeholder="Try BigQuery, #243, session windows…"></label><label class="field">DOMAIN<select id="bank-domain"><option value="0">All five domains</option>${D.domains.map(d=>`<option value="${d.id}" ${bank.domain===d.id?'selected':''}>0${d.id} · ${e(d.name)}</option>`).join('')}</select></label><label class="field">COLLECTION<select id="bank-origin"><option value="all">All questions</option><option value="authored" ${bank.origin==='authored'?'selected':''}>50 original scenarios</option><option value="imported" ${bank.origin==='imported'?'selected':''}>349 imported questions</option></select></label><label class="field">REVIEW STATUS<select id="bank-status">${[['all','All statuses'],['reviewed','Evidence-linked / reviewed'],['corrected','Corrected keys'],['needs-review','Needs further review'],['disputed','Disputed keys'],['legacy','Legacy wording'],['incomplete','Missing diagrams']].map(([v,t])=>`<option value="${v}" ${bank.status===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="check-field"><input type="checkbox" id="bank-saved" ${bank.saved?'checked':''}>Saved questions</label><label class="check-field"><input type="checkbox" id="bank-incorrect" ${bank.incorrect?'checked':''}>Needs practice</label></div><div id="bank-results">${bankResults()}</div>`;}
function richHTML(html){return html.replace(/<img\s+[^>]*src="assets\/images\/([^"/]+)"[^>]*>/g,(whole,file)=>{const a=D.assets[file],src='assets/images/'+file;if(a?.placeholder)return `<span class="asset-warning">This diagram is an unreadable ${a.width} × ${a.height} px placeholder in the uploaded archive.<a href="${e(src)}" target="_blank" rel="noopener">Open the preserved source file ↗</a></span>`;return `<button type="button" class="image-open" data-action="open-image" data-file="${e(file)}" aria-label="Open original diagram at full size">${whole}</button><span class="image-caption">Original supplied image · tap to inspect</span>`;});}
function choicesHTML(q,selected,checked=false){return `<fieldset class="choices"><legend>${q.required>1?'Select exactly '+q.required+' options.':'Select one option.'}</legend>${q.choices.map(c=>{const picked=selected.includes(c.letter),right=checked&&q.answer.includes(c.letter),wrong=checked&&picked&&!right;return `<div class="choice ${picked?'selected':''} ${q.gradable&&right?'correct':''} ${q.gradable&&wrong?'wrong':''}" data-choice="${c.letter}"><input type="${q.required>1?'checkbox':'radio'}" name="answer" value="${c.letter}" id="answer-${c.letter}" aria-label="${e(c.letter+'. '+(c.transcription||c.text||'Original image alternative'))}" ${picked?'checked':''} ${checked?'disabled':''}><div id="choice-${c.letter}" class="choice-text rich" data-english><span class="choice-letter">${c.letter}.</span>${c.transcription?`<code>${e(c.transcription)}</code><details class="details"><summary>Original image</summary>${richHTML(c.html)}</details>`:richHTML(c.html||e(c.text))}</div>${q.gradable&&checked&&(right||wrong)?`<span class="choice-result">${right?'✓ Correct':'× Selected'}</span>`:''}</div>`;}).join('')}</fieldset>`;}
function englishSide(text){const lower=text.toLowerCase(),matched=D.glossary.filter(g=>lower.includes(g.term.toLowerCase())).slice(0,9);return `<section class="panel english-card"><h3>The English behind the question</h3><p class="small" lang="es">Toca un término para aprender su significado y guardarlo.</p><div class="word-list">${(matched.length?matched:D.glossary.filter(g=>['v2','v4','v6'].includes(g.id))).map(g=>`<button class="word-pill" data-action="word" data-id="${g.id}">${e(g.term)}</button>`).join('')}</div></section>`;}
function feedback(q,selected){const match=C.equalAnswers(selected,q.answer),verified=q.gradable;return `<section class="answer-box" id="answer-feedback" tabindex="-1"><div class="answer-key">${tag(verified?(match?'✓ Your answer fits':'Review the decision'):(match?'Matches the imported key':'Differs from the imported key'),verified?(match?'green':'amber'):'amber')}${tag((q.status==='corrected'?'Editorial answer: ':'Answer key: ')+q.answer.join(', '),'blue')}</div><h2>${verified?'Why this answer fits':'Read the key with its limitations'}</h2>${q.status==='corrected'?`<div class="notice info">The source marked <strong>${q.sourceAnswer.join(', ')}</strong>. Editorial correction: <strong>${q.answer.join(', ')}</strong>. The original key is preserved.</div>`:''}<p data-english>${e(q.explanation||q.sourceExplanation)}</p>${q.origin==='imported'?`<p class="small muted">${e(q.reviewNote)}</p>`:''}${q.choices.some(c=>c.why)?`<h3 style="margin-top:24px">Check every alternative</h3>${q.choices.map(c=>`<div class="reason-row"><strong>${c.letter}${q.answer.includes(c.letter)?' ✓':''}</strong><p data-english>${e(c.why)}</p></div>`).join('')}`:''}${q.sourceExplanation&&q.explanation?`<details class="details"><summary>Read the original imported explanation</summary><p data-english>${e(q.sourceExplanation)}</p></details>`:''}<h3 style="margin-top:24px">${verified?'Documentation for the explanation':'Related official reading · not independent key validation'}</h3>${refs(q.references)}${q.sources.length?`<details class="details"><summary>Imported question provenance</summary>${q.sources.map(url=>`<p class="small"><a href="${e(url)}" target="_blank" rel="noopener noreferrer">ExamBase original question page ↗</a></p>`).join('')}<p class="small muted">Third-party practice material supplied in your archive. It is not represented as an official Google exam item.</p></details>`:''}</section>`;}
function questionBody(q){return q.text.length>2800?`<details class="case-study"><summary>Read the complete supplied case study and question</summary><div class="rich" data-english>${richHTML(q.html)}</div></details><p class="rich" data-english>${e(q.text.slice(-750))}</p>`:`<div class="rich" data-english>${richHTML(q.html)}</div>`;}
function renderQuestion(id){const q=Q[id];if(!q)return renderBank();if(practice.id!==id)practice={id,selected:[],checked:false};const saved=state.bookmarks.includes(id),idx=D.questions.indexOf(q),next=D.questions[(idx+1)%D.questions.length];return `<a href="#practice" class="back-link">← Back to question bank</a><div class="study-grid"><article class="question-card"><div class="question-toolbar"><div class="meta">${statusTag(q)}${tag('Domain 0'+q.domain)}</div><button class="button small" data-action="bookmark" data-id="${id}" aria-pressed="${saved}">${saved?'★ Saved':'☆ Save question'}</button></div><h1>${qlabel(q)}</h1>${!q.gradable?`<div class="notice ${q.status==='disputed'?'danger':''}">${q.status==='unreviewed'?'This key and its explanation are imported and not independently verified. Your selection is compared with the source, without counting it toward verified accuracy.':e(q.reviewNote)}</div>`:''}${q.issues.length?`<div class="notice">${q.issues.map(e).join('<br>')}</div>`:''}${questionBody(q)}${choicesHTML(q,practice.selected,practice.checked)}<div class="check-actions"><button class="button primary" data-action="${practice.checked?'retry-question':'check-answer'}">${practice.checked?'Try again':q.gradable?'Check my answer':'Compare with source key'}</button><a class="button" href="#practice/${next.id}">Next question →</a></div>${practice.checked?feedback(q,practice.selected):''}</article><aside class="study-side">${englishSide(q.text+' '+q.choices.map(c=>c.text).join(' '))}<section class="panel"><h3>Connect it to the concept</h3><p class="muted">${e(domain(q.domain).name)}</p><a class="text-link" href="#learn/${q.lesson}">${e(L[q.lesson]?.title||'Open a related lesson')} →</a></section><section class="panel"><h3>Separate the requirement from the clue</h3><p data-english>Identify the access pattern, latency target, consistency requirement and operational overhead. Choose the option satisfying all the stated constraints.</p></section></aside></div>`;}
function englishCards(){const list=D.glossary.filter(g=>(!english.saved||state.vocab[g.id])&&(!english.query||(g.term+' '+g.es+' '+g.meaning).toLowerCase().includes(english.query.toLowerCase())));return `<div class="small muted" style="margin-bottom:18px">${list.length} terms · ${Object.values(state.vocab).filter(v=>v.known).length} marked familiar</div><div class="vocab-grid">${list.map(g=>`<article class="vocab-card"><div class="meta">${tag('Technical + exam English','amber')}<button class="saved-star" data-action="save-word" data-id="${g.id}" aria-label="${state.vocab[g.id]?'Remove':'Save'} ${e(g.term)}" aria-pressed="${!!state.vocab[g.id]}">${state.vocab[g.id]?'★':'☆'}</button></div><h2>${e(g.term)}</h2><p>${e(g.meaning)}</p><details><summary>Spanish meaning</summary><span lang="es">${e(g.es)}</span></details><div class="vocab-actions"><button class="button small" data-action="word" data-id="${g.id}">Learn the phrase ↗</button><button class="button quiet small" data-action="speak" data-id="${g.id}" aria-label="Listen to ${e(g.term)}">▶ Listen</button></div></article>`).join('')}</div>${!list.length?'<div class="empty"><h2>Your wordbook starts with a word.</h2><p>Save any underlined term or clear the search to explore the glossary.</p></div>':''}`;}
function flashcard(){const saved=D.glossary.filter(g=>state.vocab[g.id]);if(!english.deck.length)english.deck=(saved.length?saved:D.glossary).map(g=>g.id);const pool=english.deck.map(id=>G[id]);english.index%=pool.length;const g=pool[english.index];return `<div class="small muted">${saved.length?'Your saved terms':'Exploring the complete glossary'} · card ${english.index+1} of ${pool.length}</div><section class="flashcard"><div class="mini-label">RECALL THE MEANING</div><h2>${e(g.term)}</h2>${english.flipped?`<p class="translation" lang="es">${e(g.es)}</p><p class="small muted">${e(g.meaning)}</p><p class="example">“${e(g.example)}”</p><div class="flash-actions"><button class="button" data-action="flash-again" data-id="${g.id}">Review again</button><button class="button primary" data-action="flash-known" data-id="${g.id}">I know this →</button></div>`:`<p class="small muted" lang="es">Recuerda el significado en español antes de revelar la respuesta.</p><div class="flash-actions"><button class="button primary" data-action="flip-card">Reveal meaning</button><button class="button" data-action="speak" data-id="${g.id}">▶ Listen</button></div>`}</section><p class="small muted" style="text-align:center">Familiarity is self-reported. Your saved terms and recall choices stay in this browser.</p>`;}
function renderEnglish(){return `<div class="page-heading"><div><div class="eyebrow">UNDERSTAND THE QUESTION, TOO</div><h1>Better English.<br>Clearer decisions.</h1><p class="lead">Learn technical vocabulary and the small phrases that change an exam requirement. Tap underlined language anywhere in your lessons and practice.</p></div><div class="meta">${tag(Object.keys(state.vocab).length+' saved words','amber')}</div></div><div class="tabs" role="tablist" aria-label="English study mode"><button class="tab ${english.mode==='list'?'active':''}" role="tab" aria-selected="${english.mode==='list'}" data-action="english-mode" data-mode="list">Wordbook · 101 terms</button><button class="tab ${english.mode==='flash'?'active':''}" role="tab" aria-selected="${english.mode==='flash'}" data-action="english-mode" data-mode="flash">Recall cards</button></div>${english.mode==='list'?`<div class="filterbar"><label class="field grow">FIND A WORD OR MEANING<input type="search" id="term-search" placeholder="Try throughput, recuperar, while minimizing…" value="${e(english.query)}"></label><label class="check-field"><input type="checkbox" id="term-saved" ${english.saved?'checked':''}>Only my saved terms</label></div><div id="english-results">${englishCards()}</div>`:flashcard()}<details class="details" style="margin-top:28px"><summary>How to read a difficult exam sentence</summary><p data-english>“You need to ensure low latency while minimizing operational overhead.”</p><p lang="es"><strong>You need to ensure</strong> = debes garantizar. <strong>Low latency</strong> = poca demora. <strong>While minimizing</strong> = al mismo tiempo, reducir al mínimo. <strong>Operational overhead</strong> = esfuerzo continuo de administración.</p><p class="small muted">Plain English: deliver results quickly and choose an approach that is easy to operate. Both constraints matter.</p></details>`;}
const RECIPES={
 stream:{name:'Live sensor analytics',goal:'Analyze events continuously while keeping producers decoupled from processing.',steps:[['Devices','Timestamp each event at its source.','Preserve event IDs and the original event time.'],['Pub/Sub','Publish and buffer messages.','Subscriptions separate producer availability from downstream processing.'],['Dataflow','Validate, group and transform events.','Use Beam event-time windows and an explicit late-data policy.'],['BigQuery','Store the analytical result.','Choose a write contract and query-aligned table layout.']],refs:['dataflow','beam','write']},
 sql:{name:'Daily warehouse transformations',goal:'Build repeatable SQL models and reject invalid curated results.',steps:[['Source tables','Load a documented staging schema.','Define ownership, freshness and the meaning of each field.'],['Dataform','Version SQL and its dependencies.','Express models as a graph and reuse named definitions.'],['Assertions','Check the output contract.','Test unique keys, null rules and business conditions.'],['Curated tables','Publish validated analytical outputs.','Expose a documented data product through controlled access.']],refs:['dataform','dependencies','sharing']},
 spark:{name:'Existing Spark migration',goal:'Preserve an existing processing ecosystem under a short migration deadline.',steps:[['Existing jobs','Inventory dependencies and inputs.','Check library compatibility and required filesystem behavior.'],['Cloud Storage','Separate durable inputs from workers.','Retain documented files independently of cluster lifetime.'],['Dataproc / Spark','Run the existing processing model.','Compare job-based execution against persistent clusters.'],['Warehouse output','Validate and publish results.','Reconcile business totals before switching consumers.']],refs:['spark','transfer']},
 rag:{name:'A grounded document assistant',goal:'Retrieve relevant and permitted document context before generating an answer.',steps:[['Documents','Parse and split useful passages.','Keep source IDs, dates and access metadata with each chunk.'],['Embeddings','Represent chunk meaning numerically.','Use a consistent model and an appropriate retrieval strategy.'],['Retrieval','Find useful, authorized context.','Evaluate relevance and apply access restrictions.'],['Generation','Answer using retrieved evidence.','Preserve citations and evaluate the resulting answer.']],refs:['vectors','ai']}
};
function streamPanel(){const s=C.simulateStream(lab.step,lab.late);return `<div class="lab-grid"><section class="lab-controls"><label class="field">ALLOWED LATENESS<select id="lab-late">${[0,3,10].map(n=>`<option value="${n}" ${lab.late===n?'selected':''}>${n} minutes after window end</option>`).join('')}</select></label><div><button class="button primary" data-action="stream-next" ${lab.step===C.EVENTS.length?'disabled':''}>Process next event →</button></div><button class="button small" data-action="reset-lab">Reset experiment</button><p>Fixed five-minute windows. Window intervals include the start and exclude the end. Values are illustrative units.</p><p>In this teaching model, watermark = highest event time observed − 2 minutes, with a minimum of 0. A record is dropped when the previous watermark is at or beyond window end + allowed lateness. This is an explicit simulation rule, not Dataflow’s watermark algorithm.</p></section><section class="lab-display"><div class="meta">${tag('EVENT TIME ≠ ARRIVAL TIME','blue')}${tag('Watermark: '+s.watermark+' min')}</div><h2 style="margin-top:16px">Where does a delayed event belong?</h2><p class="small muted" data-english>Process the records in arrival order. Event D was created at minute 2 but arrives at minute 10. Compare 0 and 3 minutes of allowed lateness.</p><div class="event-queue" aria-label="Arrival-ordered events">${C.EVENTS.map((v,i)=>`<span class="event-token ${i<lab.step?(s.history[i].accepted?'done':'drop'):i===lab.step?'next':''}">${v.id}<small>t = ${v.time}</small></span>`).join('')}</div><div class="windows" aria-label="Window totals">${s.windows.map(w=>`<div class="window-box ${w.expired?'closed':''}"><h3>[${w.start}, ${w.end}) minutes</h3><strong>${w.total}</strong><p>Value units · ${w.ids.length?'events '+w.ids.join(', '):'no events yet'}</p>${tag(w.expired?'Expired':'Accepting allowed data',w.expired?'':'blue')}</div>`).join('')}</div><div class="metric-row"><div class="metric"><strong>${lab.step} / 6</strong><span>Events processed</span></div><div class="metric"><strong>${s.total}</strong><span>Accepted value units</span></div><div class="metric"><strong>${s.dropped}</strong><span>Dropped events</span></div></div><div class="notice info" aria-live="polite">${lab.step?(()=>{const h=s.history.at(-1);return `Event ${h.id}: created at ${h.time} min, arrived at ${h.arrival} min. Before arrival, the watermark was ${h.watermarkBefore} min. ${h.accepted?'Accepted into its event-time window'+(h.late?' despite its delay':'')+'.':'Dropped because its window had expired under the selected policy.'}`;})():'Start with event A. Change the allowed lateness to compare the same record sequence.'}</div>${s.history.length?`<div class="table-wrap"><table><caption class="sr-only">Processing history in arrival order</caption><thead><tr><th>Event</th><th>Event time</th><th>Arrival</th><th>Value</th><th>Decision</th></tr></thead><tbody>${s.history.map(h=>`<tr><td>${h.id}</td><td>${h.time} min</td><td>${h.arrival} min</td><td>${h.value}</td><td>${h.accepted?'Accepted':'Dropped'}${h.late?' · delayed':''}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="small" style="margin-top:20px">Read the model: ${doclink('beam')}</div></section></div>`;}
function scanPanel(){const m=C.scanModel(lab.days,lab.country);return `<div class="lab-grid"><section class="lab-controls"><label class="field">DAYS QUERIED: <strong id="day-count">${lab.days} / 30</strong><input type="range" id="scan-days" min="1" max="30" step="1" value="${lab.days}"></label><label class="field">COUNTRY FILTER<select id="scan-country"><option value="CL" ${lab.country==='CL'?'selected':''}>One country out of ten</option><option value="all" ${lab.country==='all'?'selected':''}>All countries</option></select></label><button class="button small" data-action="reset-lab">Reset experiment</button><p>Illustrative dataset: 30 days × 10 GB/day = 300 GB across the referenced columns. Ten countries have equal volumes.</p><p>The model assumes ideal date pruning and ideal country-block pruning. Real BigQuery storage blocks, query plans and billable bytes differ. These are teaching values, not a billing estimate.</p></section><section class="lab-display"><div class="eyebrow">READ LESS DATA, DO LESS WORK</div><h2>What changes when storage matches the query?</h2><p class="small muted" data-english>Hold the dataset and query columns fixed. Change the date range and country filter to compare three storage layouts.</p><div id="scan-output">${scanOutput(m)}</div><p class="small muted">Partitioning uses the date predicate. Clustering can further skip irrelevant country blocks. Actual clustered bytes are only known after execution.</p>${refs(['partition','cluster','prune'])}</section></div>`;}
function scanOutput(m){return `<div role="img" aria-label="Logical scan comparison: unorganized ${m.full} GB, partitioned ${m.partitioned} GB, partitioned and clustered ${m.clustered} GB.">${[['Unorganized layout',m.full,'#a2adc2'],['Date-partitioned',m.partitioned,'#7892d6'],['Partitioned + country-clustered',m.clustered,'#3159c9']].map(([name,n,color])=>`<div class="scan-row"><div class="scan-head"><span>${name}</span><strong>${Number(n.toFixed(1))} GB</strong></div><div class="scan-bar"><span style="--value:${100*n/300}%;--color:${color}"></span></div></div>`).join('')}</div><div class="notice success" aria-live="polite">In this idealized model, the combined layout reads ${Math.round((1-m.clustered/300)*100)}% fewer logical bytes than the unorganized layout.</div><pre><code>SELECT SUM(amount)
FROM demo.sales
WHERE event_date &gt;= DATE_SUB(DATE '2026-11-01', INTERVAL ${m.days} DAY)
  AND event_date &lt; DATE '2026-11-01'${lab.country==='all'?'':"\n  AND country = 'CL'"};</code></pre>`;}
function recipePanel(){const r=RECIPES[lab.recipe];return `<div class="lab-grid"><section class="lab-controls"><label class="field">BUSINESS SCENARIO<select id="recipe-select">${Object.entries(RECIPES).map(([id,v])=>`<option value="${id}" ${lab.recipe===id?'selected':''}>${e(v.name)}</option>`).join('')}</select></label><p>Follow one record or document through a complete pattern. The named transition on each step explains the relationship; other architectures may also satisfy different constraints.</p><a class="button small" href="#learn/processing-engine">Compare the engines →</a></section><section class="lab-display"><h2>${e(r.name)}</h2><p class="lead" data-english>${e(r.goal)}</p><div class="recipe-grid">${r.steps.map((s,i)=>`<article class="recipe-step"><div class="meta">${tag('STEP 0'+(i+1),'blue')}<span>${i===3?'Deliver the result':'Output becomes the next input →'}</span></div><h3>${e(s[0])}</h3><p><strong>${e(s[1])}</strong></p><p data-english style="margin-top:8px">${e(s[2])}</p></article>`).join('')}</div><h3 style="margin-top:25px">Check the details</h3>${refs(r.refs)}</section></div>`;}
function renderLab(){return `<div class="page-heading"><div><div class="eyebrow">MAKE THE CONCEPT VISIBLE</div><h1>Change one thing.<br>See what follows.</h1><p class="lead">Work through small, explicit models of streaming behavior and query layout. Every number and assumption is shown.</p></div></div><div class="tabs" aria-label="Choose an interactive lab">${[['stream','Late events & windows'],['scan','Partitioning & scanning'],['recipes','Architecture patterns']].map(([id,t])=>`<button class="tab ${lab.tab===id?'active':''}" data-action="lab-tab" data-id="${id}" aria-pressed="${lab.tab===id}">${t}</button>`).join('')}</div>${lab.tab==='stream'?streamPanel():lab.tab==='scan'?scanPanel():recipePanel()}`;}
function sourceCards(){const list=Object.values(D.sources).filter(s=>(s.title+' '+s.topic+' '+s.publisher).toLowerCase().includes(sourceQuery.toLowerCase()));return `<div class="small muted" style="margin-bottom:18px">${list.length} primary references</div><div class="source-grid">${list.map(s=>`<article class="source-card"><div class="meta">${tag(s.topic,'blue')}<span>${e(s.publisher)}</span></div><h3><a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)} ↗</a></h3><div class="small muted">Reference checked · ${e(s.checked)}</div></article>`).join('')}</div>`;}
function renderSources(){const a=D.importAudit;return `<div class="page-heading"><div><div class="eyebrow">TRACE THE REASONING</div><h1>Know where the answer comes from.</h1><p class="lead">Primary documentation supports the learning notes. Imported keys remain identifiable third-party claims. Review status is part of the study material.</p></div></div><div class="download-row"><a class="button primary" href="data/study-pack.json" download="data-engineer-study-pack.json">Download study pack · JSON ↓</a><a class="button" href="data/study-notes.md" download="data-engineer-study-notes.md">Study notes · Markdown ↓</a><button class="button" data-action="export-progress">Export my progress ↓</button><button class="button" data-action="import-progress">Restore progress ↑</button></div><div class="audit-grid"><section class="panel"><h2>The official blueprint</h2><p>The standard exam lists five domains with approximate weights. This app covers all 19 numbered objectives through 25 original lessons. Domain titles below are concise study labels.</p><div class="table-wrap"><table class="coverage-table"><thead><tr><th>Study domain</th><th>Weight</th><th>Objectives</th></tr></thead><tbody>${D.domains.map(d=>`<tr><td><a href="#learn/${domainLessons(d.id)[0].id}">${d.id}. ${e(d.name)}</a></td><td>~${d.weight}%</td><td>${Object.keys(d.objectives).join(' · ')}</td></tr>`).join('')}</tbody></table></div><p style="margin-top:18px">Standard format: 2 hours, 40–50 multiple-choice and multiple-select questions; English or Japanese. Registration and current policies belong to the official certification page.</p>${refs(['exam','guide'])}<p>The guide’s Dataplex and Dataproc terminology is retained for study. Live documentation may use Knowledge Catalog or managed Apache Spark naming. Check the reference when implementing a solution.</p></section><section class="panel"><h2>The supplied archive, audited</h2><p>All 349 numbered questions and 25 image files are retained. The original archive had 26 missing explanations; each now has an editorial explanation or a technical limitation note.</p><div class="table-wrap"><table><thead><tr><th>Imported status</th><th>Count</th></tr></thead><tbody>${Object.entries(a.statusCounts).map(([s,n])=>`<tr><td>${e({unreviewed:'Source key only',reviewed:'Editorial review',corrected:'Key corrected',disputed:'Key disputed',incomplete:'Missing diagram',legacy:'Legacy wording',conditional:'Conditional answer'}[s])}</td><td>${n}</td></tr>`).join('')}</tbody></table></div><p style="margin-top:17px">Ten images are 9 × 6 pixel placeholders affecting eight questions. Their missing content is not reconstructed or treated as verified.</p><p>Keys corrected with explicit notes: ${a.correctedKeys.map(n=>`<a href="#practice/imp-${n}">#${n}</a>`).join(', ')}. Unreviewed source comparisons do not count toward verified accuracy. All imported items are excluded from timed practice.</p></section></div><details class="details"><summary>Objective-to-lesson mapping</summary><div class="table-wrap"><table><thead><tr><th>Objective</th><th>Focus</th><th>Lessons</th></tr></thead><tbody>${D.domains.flatMap(d=>Object.entries(d.objectives).map(([obj,title])=>`<tr><td>${obj}</td><td>${e(title)}</td><td>${D.lessons.filter(l=>l.objective===obj).map(l=>`<a href="#learn/${l.id}">${e(l.title)}</a>`).join('<br>')}</td></tr>`)).join('')}</tbody></table></div></details><div class="notice info">Independent learning material. The original scenarios are not official exam questions. Practice scores are learning feedback and do not predict certification results. Progress and saved words are stored in this browser; use the export to move them between devices.</div><div class="section-head"><h2>The reference shelf</h2></div><div class="filterbar"><label class="field grow">FIND A SOURCE<input type="search" id="source-search" value="${e(sourceQuery)}" placeholder="Try security, streaming, BigQuery…"></label></div><div id="source-results">${sourceCards()}</div>`;}
function finishExam(){const ex=state.exam;if(!ex)return;ex.finished=true;if(!ex.recorded){const score=C.scoreExam(ex.ids,ex.answers,Q);for(const it of score.items)state.attempts.push({id:it.id,selected:it.picked,correct:it.correct,verified:true,at:Date.now()});state.attempts=state.attempts.slice(-2000);ex.recorded=true;}save();}
function examSetup(){return `<div class="page-heading"><div><div class="eyebrow">A QUIET PLACE TO PRACTICE</div><h1>Put your decisions<br>under a little pressure.</h1><p class="lead">A weighted set of original, evidence-linked questions. Save answers, move freely and review every explanation when you finish.</p></div></div><div class="exam-intro"><section class="exam-config"><h2>Set up your session</h2><p class="small muted">Choose a short drill or a full-length practice format.</p><label class="field">SESSION LENGTH<select id="exam-size"><option value="10">10 questions · 24 minutes</option><option value="20">20 questions · 48 minutes</option><option value="40" selected>40 questions · 120 minutes</option><option value="50">50 questions · 120 minutes</option></select></label><div class="notice info">Questions are sampled from the 50 original learning scenarios. Domain allocation follows approximate official weights. This finite practice pool is not an official or predictive test.</div><button class="button primary" data-action="start-exam">Begin timed practice →</button></section><section class="panel"><h3>What to expect</h3><ul class="exam-guide"><li>Your session resumes after a refresh, with the original deadline.</li><li>Answers remain hidden until you finish or time runs out.</li><li>Use the numbered navigator to revisit any question.</li><li>The official exam also has multiple-select items. Those appear in the imported study bank; this original timed pool currently uses single-select scenarios.</li><li>Vocabulary help remains available as a learning aid. This is an open study session.</li></ul><a class="text-link" href="#sources">Review sources and question provenance →</a></section></div>`;}
function examResults(){const ex=state.exam,s=C.scoreExam(ex.ids,ex.answers,Q);return `<div class="page-heading"><div><div class="eyebrow">REVIEW IS WHERE LEARNING HAPPENS</div><h1>Make the next attempt better.</h1><p class="lead">Use the explanation to revise your reasoning. This score describes this practice session only.</p></div><button class="button primary" data-action="new-exam">Set up another session →</button></div><div class="study-grid"><section><div class="panel result-summary"><div class="score-ring"><strong>${s.percent}%</strong><span>${s.correct} / ${s.total} correct</span></div><p class="small muted">${s.unanswered} unanswered · all questions count equally · no partial credit</p><p class="small">No official passing score is implied.</p></div><div class="section-head"><h2>Review every decision</h2></div>${s.items.map((it,i)=>{const q=Q[it.id];return `<details class="result-row"><summary>${tag(it.correct?'✓ Correct':it.unanswered?'Unanswered':'Review',it.correct?'green':'amber')}<span>${i+1}. ${e(q.text.slice(0,120))}${q.text.length>120?'…':''}</span></summary><div class="result-explain"><h3 data-english>${e(q.text)}</h3><p class="small">Your selection: <strong>${it.picked.join(', ')||'None'}</strong> · Answer: <strong>${q.answer.join(', ')}</strong></p>${q.choices.map(c=>`<div class="reason-row"><strong>${c.letter}${q.answer.includes(c.letter)?' ✓':''}</strong><div><p>${e(c.text)}</p><p class="muted" data-english>${e(c.why)}</p></div></div>`).join('')}${refs(q.references)}<a class="text-link" href="#learn/${q.lesson}">Revisit the concept →</a></div></details>`;}).join('')}</section><aside class="study-side"><section class="panel"><h3>Performance by domain</h3>${D.domains.map(d=>{const v=s.domains[d.id]||{correct:0,total:0};return `<div style="margin:17px 0"><div class="scan-head"><span>${e(d.name)}</span><strong>${v.correct}/${v.total}</strong></div><div class="progress-track"><span class="progress-fill" style="--value:${v.total?100*v.correct/v.total:0}%"></span></div></div>`;}).join('')}</section><section class="panel english-card"><h3>Read the requirement again</h3><p lang="es">Antes de repetir, identifica qué palabra o condición cambió la decisión: consistencia, latencia, costo o administración.</p><a class="text-link" href="#english">Practice English recall →</a></section></aside></div>`;}
function renderExam(){const ex=state.exam;if(!ex)return examSetup();if(ex.deadline<=Date.now()&&!ex.finished)finishExam();if(ex.finished)return examResults();const q=Q[ex.ids[ex.index]],picked=ex.answers[q.id]||[];return `<div class="exam-header"><div><div class="eyebrow">TIMED PRACTICE · ORIGINAL SCENARIOS</div><h1>Question ${ex.index+1} <span class="muted">/ ${ex.ids.length}</span></h1><div class="meta">${tag(domain(q.domain).name,'blue')}<span>Answers are hidden until the session ends.</span></div></div><div id="exam-timer" class="exam-timer" role="timer" aria-label="Time remaining">${timeLeft(ex.deadline)}</div></div><div class="study-grid"><article class="question-card">${questionBody(q)}${choicesHTML(q,picked,false)}<div class="check-actions"><button class="button" data-action="exam-move" data-dir="-1" ${ex.index===0?'disabled':''}>← Previous</button>${ex.index<ex.ids.length-1?'<button class="button primary" data-action="exam-move" data-dir="1">Save & next →</button>':'<button class="button primary" data-action="finish-exam">Finish & review →</button>'}</div></article><aside class="study-side"><section class="panel"><h3>Question navigator</h3><p class="small muted">${Object.values(ex.answers).filter(a=>a.length).length} answered · blue fill means an answer is saved.</p><div class="exam-nav">${ex.ids.map((id,i)=>`<button data-action="exam-jump" data-index="${i}" class="${ex.answers[id]?.length?'answered':''} ${ex.index===i?'current':''}" aria-label="Question ${i+1}${ex.answers[id]?.length?', answered':''}${ex.index===i?', current':''}" ${ex.index===i?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><button class="button small" style="width:100%;margin-top:20px" data-action="finish-exam">Finish session</button></section>${englishSide(q.text)}</aside></div>`;}
function timeLeft(deadline){const n=Math.max(0,Math.ceil((deadline-Date.now())/1000));return `${String(Math.floor(n/3600)).padStart(2,'0')}:${String(Math.floor(n%3600/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function renderSearch(term){const s=term.toLowerCase().trim(),lessons=D.lessons.filter(l=>(l.title+' '+l.lead+' '+l.sections.map(x=>x.body).join(' ')).toLowerCase().includes(s)),questions=D.questions.filter(q=>q.text.toLowerCase().includes(s)||String(q.number)===s),terms=D.glossary.filter(g=>(g.term+' '+g.es).toLowerCase().includes(s));return `<div class="page-heading"><div><div class="eyebrow">YOUR CONNECTED NOTES</div><h1>Search: ${e(term)}</h1><p class="lead">${lessons.length} lessons · ${questions.length} questions · ${terms.length} vocabulary terms</p></div></div><section class="search-section"><h2>Lessons</h2>${lessons.length?lessons.slice(0,12).map(l=>`<div class="search-result"><h3><a href="#learn/${l.id}">${e(l.title)}</a></h3><p>${e(l.lead)}</p></div>`).join(''):'<p class="small muted">No matching lessons.</p>'}</section><section class="search-section"><h2>Vocabulary</h2><div class="word-list">${terms.slice(0,20).map(g=>`<button class="word-pill" data-action="word" data-id="${g.id}">${e(g.term)}</button>`).join('')||'<p class="small muted">No matching terms.</p>'}</div></section><section class="search-section"><h2>Questions</h2><div class="question-list">${questionRows(questions.slice(0,12))||'<p class="small muted">No matching questions.</p>'}</div>${questions.length>12?`<button class="button" style="margin-top:20px" data-action="search-bank" data-query="${e(term)}">See all ${questions.length} matching questions →</button>`:''}</section>`;}
const termByText=new Map(D.glossary.map(g=>[g.term.toLowerCase(),g]));
const termRegex=new RegExp('\\b('+D.glossary.map(g=>g.term).sort((a,b)=>b.length-a.length).map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')\\b','gi');
function highlight(root=$('#main')){if(!state.english)return;for(const el of root.querySelectorAll('[data-english]')){const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT,{acceptNode(n){return n.parentElement.closest('button,a,code,pre,script,style,summary,textarea,svg')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT;}}),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){const text=node.nodeValue;termRegex.lastIndex=0;let match,index=0,fragment=document.createDocumentFragment(),found=false;while((match=termRegex.exec(text))){found=true;fragment.append(document.createTextNode(text.slice(index,match.index)));const g=termByText.get(match[0].toLowerCase()),button=document.createElement('button');button.type='button';button.className='term';button.dataset.action='word';button.dataset.id=g.id;button.textContent=match[0];button.setAttribute('aria-label',`Learn “${match[0]}” in English and Spanish`);fragment.append(button);index=match.index+match[0].length;}if(found){fragment.append(document.createTextNode(text.slice(index)));node.replaceWith(fragment);}}}}
function render(scroll=false){let parts;try{parts=(location.hash.slice(1)||'home').split('/').map(decodeURIComponent);}catch{parts=['home'];}route=parts[0];renderNav(route);let html;try{switch(route){case'home':html=renderHome();break;case'learn':html=renderLearn(parts[1]);break;case'practice':html=parts[1]?renderQuestion(parts[1]):renderBank();break;case'english':html=renderEnglish();break;case'lab':html=renderLab();break;case'exam':html=renderExam();break;case'sources':html=renderSources();break;case'search':html=renderSearch(parts.slice(1).join('/'));break;default:html=renderHome();route='home';}}catch(error){console.error(error);html='<div class="empty"><h1>This view could not load.</h1><p>Your exported study notes are still available.</p><a href="data/study-notes.md">Read study notes</a></div>';}$('#main').innerHTML=html;highlight();document.title=(route==='home'?'Learn with understanding':$('#main h1')?.textContent||'Study')+' · Data Engineer Fieldnotes';if(scroll){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}document.body.classList.remove('nav-open');$('#menu-toggle').setAttribute('aria-expanded','false');}
function openWord(id){const g=G[id];if(!g)return;$('#vocab-content').innerHTML=`<button class="dialog-close" data-action="close-word" aria-label="Close vocabulary definition">×</button><div class="mini-label">ENGLISH FIELDNOTES</div><h2 id="vocab-title">${e(g.term)}</h2><p class="vocab-definition">${e(g.meaning)}</p><div class="translation-box"><div class="mini-label">EN ESPAÑOL</div><p lang="es">${e(g.es)}</p></div><p class="vocab-example">“${e(g.example)}”</p><div class="dialog-actions"><button class="button primary" data-action="save-word" data-id="${g.id}">${state.vocab[id]?'★ Saved · remove':'☆ Save to my wordbook'}</button><button class="button" data-action="speak" data-id="${id}">▶ Listen</button></div><p class="small muted" style="margin:18px 0 0">Pronunciation uses the speech voices available in your browser.</p>`;const dialog=$('#vocab-dialog');dialog.dataset.term=id;if(!dialog.open)dialog.showModal();}
function speak(id){if(!('speechSynthesis'in window)||!G[id]){toast('Pronunciation is unavailable in this browser. The definition and example remain available.');return;}const text=new SpeechSynthesisUtterance(G[id].term),voice=speechSynthesis.getVoices().find(v=>v.lang==='en-US')||speechSynthesis.getVoices().find(v=>v.lang.startsWith('en'));if(voice)text.voice=voice;text.lang='en-US';text.rate=.83;text.onerror=()=>toast('This browser could not play speech. Try an installed English voice.');speechSynthesis.cancel();speechSynthesis.speak(text);}
function download(name,value){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function syncChoice(target){const ex=route==='exam'&&state.exam&&!state.exam.finished,q=ex?Q[state.exam.ids[state.exam.index]]:Q[practice.id];if(!q||(!ex&&practice.checked))return;let selected=$$('.choices input:checked').map(i=>i.value);if(ex){state.exam.answers[q.id]=selected;save();const idx=state.exam.index,button=$(`.exam-nav button[data-index="${idx}"]`);button?.classList.toggle('answered',selected.length>0);}else practice.selected=selected;$$('.choice').forEach(el=>el.classList.toggle('selected',selected.includes(el.dataset.choice)));}
document.addEventListener('click',async ev=>{
 if(ev.target.closest('.skip')){ev.preventDefault();$('#main').focus();return;}
 const button=ev.target.closest('button[data-action]');
 if(!button){const option=ev.target.closest('.choice');if(option&&!ev.target.closest('input,button,a,summary,details')){const input=option.querySelector('input');if(!input.disabled)input.click();}return;}
 const action=button.dataset.action,id=button.dataset.id;
 switch(action){
 case'word':openWord(id);break;
 case'close-word':$('#vocab-dialog').close();break;
 case'speak':speak(id);break;
 case'save-word':if(state.vocab[id])delete state.vocab[id];else state.vocab[id]={saved:true,known:false};save();if(route==='english')render(false);if($('#vocab-dialog').open)openWord(id);else if(route!=='english')toast(state.vocab[id]?'Saved to your English wordbook.':'Removed from your wordbook.');break;
 case'complete':if(state.completed.includes(id))state.completed=state.completed.filter(x=>x!==id);else state.completed.push(id);save();render(false);toast(state.completed.includes(id)?'Lesson complete. Your learning progress is saved.':'Lesson marked incomplete.');break;
 case'copy-code':try{await navigator.clipboard.writeText(L[id].code||D.lessons.find(l=>l.id===id)?.code||'');toast('Illustrative example copied.');}catch{toast('Copy is unavailable here. Select the example text to copy it.');}break;
 case'open-question':location.hash='practice/'+id;break;
 case'clear-bank':bank={query:'',domain:0,origin:'all',status:'all',saved:false,incorrect:false,page:1};render(false);break;
 case'bank-page':bank.page=Math.max(1,bank.page+Number(button.dataset.dir));$('#bank-results').innerHTML=bankResults();$('#bank-results').scrollIntoView({block:'start'});break;
 case'bookmark':if(state.bookmarks.includes(id))state.bookmarks=state.bookmarks.filter(x=>x!==id);else state.bookmarks.push(id);save();render(false);break;
 case'check-answer':{const q=Q[practice.id];if(practice.selected.length!==q.required){toast('Select exactly '+q.required+' option'+(q.required>1?'s.':'.'));break;}practice.checked=true;state.attempts.push({id:q.id,selected:[...practice.selected],correct:C.equalAnswers(practice.selected,q.answer),verified:q.gradable,at:Date.now()});state.attempts=state.attempts.slice(-2000);save();render(false);$('#answer-feedback')?.focus({preventScroll:true});$('#answer-feedback')?.scrollIntoView({block:'nearest'});break;}
 case'retry-question':practice.selected=[];practice.checked=false;render(false);break;
 case'open-image':{const file=button.dataset.file;if(!D.assets[file])break;$('#image-content').innerHTML=`<img src="assets/images/${e(file)}" alt="Preserved original question diagram at its available resolution"><p>Original supplied image · ${D.assets[file].width} × ${D.assets[file].height} px. No missing content has been reconstructed.</p>`;$('#image-dialog').showModal();break;}
 case'close-image':$('#image-dialog').close();break;
 case'english-mode':english.mode=button.dataset.mode;english.flipped=false;english.index=0;english.deck=[];render(false);break;
 case'flip-card':english.flipped=true;render(false);break;
 case'flash-known':case'flash-again':state.vocab[id]={saved:true,known:action==='flash-known'};save();english.index++;english.flipped=false;render(false);break;
 case'lab-tab':lab.tab=id;render(false);break;
 case'stream-next':lab.step=Math.min(6,lab.step+1);render(false);break;
 case'reset-lab':lab={...lab,step:0,late:3,days:7,country:'CL'};render(false);break;
 case'export-progress':download('fieldnotes-progress.json',state);toast('Progress exported. Keep this file to move between browsers.');break;
 case'import-progress':$('#import-progress').click();break;
 case'start-exam':{const n=Number($('#exam-size').value);if(![10,20,40,50].includes(n))break;const now=Date.now(),minutes=n>=40?120:n*2.4;state.exam={ids:C.makeExam(D.questions,n,D.domains),answers:{},index:0,startedAt:now,deadline:now+minutes*60000,finished:false,recorded:false};save();render(true);break;}
 case'exam-move':if(state.exam&&!state.exam.finished){state.exam.index=Math.max(0,Math.min(state.exam.ids.length-1,state.exam.index+Number(button.dataset.dir)));save();render(true);}break;
 case'exam-jump':if(state.exam&&!state.exam.finished){state.exam.index=Number(button.dataset.index);save();render(true);}break;
 case'finish-exam':finishExam();render(true);break;
 case'new-exam':state.exam=null;save();render(true);break;
 case'search-bank':bank.query=button.dataset.query;bank.page=1;location.hash='practice';break;
 }
 if(document.activeElement===document.body&&button.dataset.action&&!['check-answer','open-question','word','open-image'].includes(action)){
  const selector=`button[data-action="${CSS.escape(action)}"]${id?`[data-id="${CSS.escape(id)}"]`:''}`;
  const replacement=document.querySelector(selector);if(replacement&&!replacement.disabled)replacement.focus({preventScroll:true});
 }
});
document.addEventListener('input',ev=>{
 const id=ev.target.id;
 if(id==='bank-query'){bank.query=ev.target.value;bank.page=1;$('#bank-results').innerHTML=bankResults();}
 if(id==='term-search'){english.query=ev.target.value;$('#english-results').innerHTML=englishCards();}
 if(id==='source-search'){sourceQuery=ev.target.value;$('#source-results').innerHTML=sourceCards();}
 if(id==='scan-days'){lab.days=Number(ev.target.value);$('#day-count').textContent=lab.days+' / 30';$('#scan-output').innerHTML=scanOutput(C.scanModel(lab.days,lab.country));}
});
document.addEventListener('change',async ev=>{
 const id=ev.target.id;
 if(ev.target.matches('.choices input')){syncChoice(ev.target);return;}
 if(['bank-domain','bank-origin','bank-status','bank-saved','bank-incorrect'].includes(id)){
  if(id==='bank-domain')bank.domain=Number(ev.target.value);if(id==='bank-origin')bank.origin=ev.target.value;if(id==='bank-status')bank.status=ev.target.value;if(id==='bank-saved')bank.saved=ev.target.checked;if(id==='bank-incorrect')bank.incorrect=ev.target.checked;bank.page=1;$('#bank-results').innerHTML=bankResults();
 }
 if(id==='term-saved'){english.saved=ev.target.checked;$('#english-results').innerHTML=englishCards();}
 if(id==='lab-late'){lab.late=Number(ev.target.value);render(false);$('#lab-late').focus({preventScroll:true});}
 if(id==='scan-country'){lab.country=ev.target.value;$('#scan-output').innerHTML=scanOutput(C.scanModel(lab.days,lab.country));}
 if(id==='recipe-select'){lab.recipe=ev.target.value;render(false);$('#recipe-select').focus({preventScroll:true});}
 if(id==='import-progress'){const file=ev.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('Progress files must be smaller than 2 MB.');const value=JSON.parse(await file.text());state=C.validateProgress(value,Object.keys(L),Object.keys(Q),Object.keys(G));save();render(false);toast('Progress restored. Unknown items were ignored safely.');}catch(error){toast('Could not restore progress: '+error.message);}ev.target.value='';}
});
$('#global-search').addEventListener('submit',ev=>{ev.preventDefault();const value=$('#search-input').value.trim();if(value)location.hash='search/'+encodeURIComponent(value);});
$('#english-toggle').addEventListener('click',()=>{state.english=!state.english;save();render(false);toast(state.english?'English help is on. Tap underlined terms.':'English help is off. The wordbook is still available.');});
$('#menu-toggle').addEventListener('click',()=>{const open=document.body.classList.toggle('nav-open');$('#menu-toggle').setAttribute('aria-expanded',String(open));if(open)$('#navigation a').focus();});
document.addEventListener('keydown',ev=>{
 if(ev.key==='/'&&!ev.target.closest('input,textarea,select,[contenteditable=true],dialog')){ev.preventDefault();$('#search-input').focus();}
 if(ev.key==='Escape'&&document.body.classList.contains('nav-open')){document.body.classList.remove('nav-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').focus();}
 if(ev.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(ev.key)){ev.preventDefault();const tabs=[...ev.target.parentElement.querySelectorAll('[role=tab]')],idx=tabs.indexOf(ev.target),next=ev.key==='Home'?0:ev.key==='End'?tabs.length-1:(idx+(ev.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();document.querySelectorAll('[role=tab]')[next]?.focus();}
});
window.addEventListener('hashchange',()=>render(true));
setInterval(()=>{if(state.exam&&!state.exam.finished){if(state.exam.deadline<=Date.now()){finishExam();if(route==='exam')render(false);else toast('Your timed session has ended. Review it in Timed practice.');}else{const el=$('#exam-timer');if(el){el.textContent=timeLeft(state.exam.deadline);el.classList.toggle('urgent',state.exam.deadline-Date.now()<300000);}}}},1000);
render(false);
})();
